window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',onScroll,{passive:true});const revealItems=[...document.querySelectorAll('.reveal, .reveal-group')];function showAllReveal(){revealItems.forEach((item)=>item.classList.add('is-visible'));}
if(!reducedMotion.matches&&'IntersectionObserver'in window){const revealObserver=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting)return;entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target);});},{rootMargin:'0px 0px -8% 0px',threshold:0.08},);revealItems.forEach((item)=>revealObserver.observe(item));}else{showAllReveal();}
const parallaxItems=[...document.querySelectorAll('[data-parallax]')];let parallaxEnabled=!reducedMotion.matches&&window.matchMedia('(min-width: 761px)').matches;function updateParallax(){if(!parallaxEnabled)return;const viewport=window.innerHeight;for(const item of parallaxItems){const rect=item.getBoundingClientRect();if(rect.bottom<-160||rect.top>viewport+160)continue;const depth=Number(item.dataset.parallax)||8;const progressValue=(rect.top+rect.height/2-viewport/2)/viewport;item.style.transform=`translate3d(0, ${(progressValue * depth).toFixed(2)}%, 0) scale(1.05)`;}}
window.addEventListener('resize',()=>{parallaxEnabled=!reducedMotion.matches&&window.matchMedia('(min-width: 761px)').matches;updateParallax();});let sceneModulePromise=null;let scenesQueued=false;function loadSceneModule(){sceneModulePromise||=import('./scene.min.js');return sceneModulePromise;}
async function bootScene(stage){if(stage.dataset.sceneBooted)return;stage.dataset.sceneBooted='true';try{const module=await loadSceneModule();if(!module.canRender3D())throw new Error('no-webgl');await module.initScene(stage);if(!stage.classList.contains('is-ready'))throw new Error('scene-not-ready');}catch{stage.classList.add('is-fallback');stage.setAttribute('tabindex','-1');}}
function queueScenes(){if(scenesQueued||!sceneStages.length)return;scenesQueued=true;const boot=()=>{if(reducedMotion.matches||navigator.connection?.saveData){sceneStages.forEach((stage)=>{stage.classList.add('is-fallback');stage.setAttribute('tabindex','-1');});return;}
if(!('IntersectionObserver'in window)){sceneStages.forEach(bootScene);return;}
const sceneObserver=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting)return;bootScene(entry.target);sceneObserver.unobserve(entry.target);});},{rootMargin:'300px 0px',threshold:0.01},);sceneStages.forEach((stage)=>sceneObserver.observe(stage));};if('requestIdleCallback'in window)requestIdleCallback(boot,{timeout:500});else window.setTimeout(boot,300);}
if(document.readyState==='complete')queueScenes();else window.addEventListener('load',queueScenes,{once:true});reducedMotion.addEventListener('change',(event)=>{if(event.matches){sceneStages.forEach((stage)=>{stage.classList.add('is-fallback');stage.setAttribute('tabindex','-1');});}});document.querySelectorAll('[data-slider]').forEach((slider)=>{const track=slider.querySelector('[data-slider-track]');const prev=slider.querySelector('[data-slider-prev]');const next=slider.querySelector('[data-slider-next]');const progressBar=slider.querySelector('[data-slider-progress]');if(!track)return;const step=()=>{const card=track.querySelector(':scope > *');if(!card)return track.clientWidth*0.8;const gap=parseFloat(getComputedStyle(track).columnGap||'24')||24;return card.getBoundingClientRect().width+gap;};const refresh=()=>{const max=track.scrollWidth-track.clientWidth;const ratio=max>0?track.scrollLeft/max:0;if(progressBar)progressBar.style.transform=`scaleX(${Math.max(0.08, ratio).toFixed(3)})`;if(prev)prev.disabled=track.scrollLeft<8;if(next)next.disabled=track.scrollLeft>max-8;};prev?.addEventListener('click',()=>track.scrollBy({left:-step(),behavior:reducedMotion.matches?'auto':'smooth'}));next?.addEventListener('click',()=>track.scrollBy({left:step(),behavior:reducedMotion.matches?'auto':'smooth'}));track.addEventListener('scroll',refresh,{passive:true});window.addEventListener('resize',refresh,{passive:true});refresh();});const filterRoot=document.querySelector('[data-portfolio-filters]');if(filterRoot){const buttons=[...filterRoot.querySelectorAll('[data-filter]')];const cards=[...document.querySelectorAll('[data-work]')];const live=document.querySelector('[data-filter-status]');buttons.forEach((button)=>{button.addEventListener('click',()=>{const filter=button.dataset.filter;buttons.forEach((other)=>{const current=other===button;other.classList.toggle('is-active',current);other.setAttribute('aria-pressed',String(current));});let shown=0;cards.forEach((card)=>{const show=filter==='all'||card.dataset.work.includes(filter);card.hidden=!show;if(show)shown++;});if(live)live.textContent=`Показано кейсов: ${shown}`;});});}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true;}catch{try{const field=document.createElement('textarea');field.value=text;field.setAttribute('readonly','');field.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(field);field.select();const ok=document.execCommand('copy');field.remove();return ok;}catch{return false;}}}
document.querySelectorAll('[data-copy]').forEach((button)=>{button.addEventListener('click',async()=>{const ok=await copyText(button.dataset.copy);const initial=button.dataset.label||button.textContent;button.dataset.label=initial;button.textContent=ok?'Скопировано':'Не получилось';window.setTimeout(()=>{button.textContent=initial;},2200);});});const contactForm=document.querySelector('[data-contact-form]');if(contactForm){const status=contactForm.querySelector('[data-form-status]');contactForm.addEventListener('submit',async(event)=>{event.preventDefault();if(!contactForm.reportValidity())return;const data=new FormData(contactForm);const name=String(data.get('name')||'').trim();const contact=String(data.get('contact')||'').trim();const task=String(data.get('task')||'').trim();const budget=String(data.get('budget')||'').trim();const message=[`Привет, Алексей! Меня зовут ${name || '...'}.`,task?`Задача: ${task}`:'',budget?`Бюджет: ${budget}`:'',`Со мной лучше связаться: ${contact}`,'Нашёл вас через сайт.',].filter(Boolean).join('\n');const button=contactForm.querySelector('button[type="submit"]');button?.setAttribute('disabled','');const copied=await copyText(message);if(status){status.hidden=false;status.textContent=copied?'Сообщение скопировано. Открываю Telegram — вставьте текст в чат.':'Открываю Telegram. Текст сообщения не удалось скопировать автоматически — напишите пару слов в чат.';}
window.open('https://t.me/Fitfuux','_blank','noopener,noreferrer');button?.removeAttribute('disabled');});}
